WFI.Data.add("quest", {
  [81730] = { "Missione di Duskwood I: sconfiggi i worgen", "Sconfiggi 10 Nightmare Runner e 10 Nightmare Weaver nella Duskwood Nightmare Incursion al Rotting Orchard e torna dal Field Captain Palandar.", "Mentre questi demoni ci distraggono qui, l'Emerald Dream si sta corrompendo in incubo. Presto, attraversa l'Emerald Dream Portal nel Twilight Grove e raggiungi la Nightmare Incursion del Rotting Orchard. Sconfiggi i worgen che trovi e torna da me.", nil, nil, 0x0cf2dd2a, 0xe1a2c79f, 0x982208ee, nil, nil, "...mm" },
  [81731] = { "Missione di Duskwood II: sconfiggi gli ogre", "Sconfiggi 3 Deranged Ogre e 3 Demented Fire Weaver nella Duskwood Nightmare Incursion al Vul'gol Ogre Mound e torna dal Field Captain Palandar.", "Mentre questi demoni ci distraggono qui, l'Emerald Dream si sta corrompendo in incubo. Presto, attraversa l'Emerald Dream Portal nel Twilight Grove e raggiungi la Nightmare Incursion del Vul'gol Ogre Mound. Sconfiggi gli ogre che trovi e torna da me.", nil, nil, 0x3bc05c8c, 0x4327bcd2, 0xb8acdaee, nil, nil, "...mm" },
  [81732] = { "Missione di Duskwood III: sconfiggi i draconidi", "Sconfiggi 3 Wyrmkin Terrorwalker e 10 Nightterror Whelp nella Duskwood Nightmare Incursion allo Yorgen Farmstead e torna dal Field Captain Palandar.", "Mentre questi demoni ci distraggono qui, l'Emerald Dream si sta corrompendo in incubo. Presto, attraversa l'Emerald Dream Portal nel Twilight Grove e raggiungi la Nightmare Incursion dello Yorgen Farmstead. Sconfiggi i draconidi che trovi e torna da me.", nil, nil, 0x4611b618, 0x85d50f0d, 0x63fabb72, nil, nil, "...mm" },
  [81733] = { "Missione di Duskwood IV: informazioni sugli ogre", "Raccogli informazioni dal Dreamwarden Thalinar nella Duskwood Nightmare Incursion nel profondo del Vul'gol Ogre Mound e torna dal Field Captain Palandar.", "Mentre questi demoni ci distraggono qui, l'Emerald Dream si sta corrompendo in incubo. Presto, attraversa l'Emerald Dream Portal nel Twilight Grove e raggiungi la Nightmare Incursion del Vul'gol Ogre Mound. Recupera un rapporto informativo dal Dreamwarden Thalinar e torna da me.", nil, nil, 0xeb1f89b8, 0x784d4e43, 0x6d3bf7e9, nil, nil, "...mm" },
  [81734] = { "Missione di Duskwood V: informazioni sui worgen", "Raccogli informazioni dal Dreamwarden Dorilar nella Duskwood Nightmare Incursion nel fienile del Rotting Orchard e torna dal Field Captain Palandar.", "Mentre questi demoni ci distraggono qui, l'Emerald Dream si sta corrompendo in incubo. Presto, attraversa l'Emerald Dream Portal nel Twilight Grove e raggiungi la Nightmare Incursion del Rotting Orchard. Recupera un rapporto informativo dal Dreamwarden Dorilar e torna da me.", nil, nil, 0x3491280c, 0x6a7927f0, 0x5c1e7963, nil, nil, "...mm" },
  [81735] = { "Missione di Duskwood VI: informazioni sui draghi", "Raccogli informazioni dalla Dreamwarden Amalia nella Duskwood Nightmare Incursion nella casa colonica dello Yorgen Farmstead e torna dal Field Captain Palandar.", "Mentre questi demoni ci distraggono qui, l'Emerald Dream si sta corrompendo in incubo. Presto, attraversa l'Emerald Dream Portal nel Twilight Grove e raggiungi la Nightmare Incursion dello Yorgen Farmstead. Recupera un rapporto informativo dalla Dreamwarden Amalia e torna da me.", nil, nil, 0xbf13966d, 0x77371b5e, 0x27d9d555, nil, nil, "...mm" },
  [81736] = { "Missione di Duskwood VII: recupera la Shadowscythe", "Recupera la Shadowscythe nella Duskwood Nightmare Incursion al piano di sopra della casa colonica del Rotting Orchard e torna dal Field Captain Palandar.", "Mentre questi demoni ci distraggono qui, l'Emerald Dream si sta corrompendo in incubo. Presto, attraversa l'Emerald Dream Portal nel Twilight Grove e raggiungi la Nightmare Incursion del Rotting Orchard. Recupera un potente manufatto noto come Shadowscythe e portamelo.", nil, nil, 0xde95a55f, 0xdc30c509, 0x65f644eb, nil, nil, "...mm" },
  [81737] = { "Missione di Duskwood VIII: recupera l'Ogre Magi Text", "Recupera un Ogre Magi Text nella Duskwood Nightmare Incursion dentro il Vul'gol Ogre Mound e torna dal Field Captain Palandar.", "Mentre questi demoni ci distraggono qui, l'Emerald Dream si sta corrompendo in incubo. Presto, attraversa l'Emerald Dream Portal nel Twilight Grove e raggiungi la Nightmare Incursion del Vul'gol Ogre Mound. Recupera un Ogre Magi Text e portamelo.", nil, nil, 0x43e217d8, 0x3becde9f, 0xc3d055ac, nil, nil, "...mm" },
  [81738] = { "Missione di Duskwood IX: recupera l'uovo di drago", "Recupera un Unhatched Green Dragon Egg nella Duskwood Nightmare Incursion allo Yorgen Farmstead, vicino al grande ceppo nei campi e torna dal Field Captain Palandar.", "Mentre questi demoni ci distraggono qui, l'Emerald Dream si sta corrompendo in incubo. Presto, attraversa l'Emerald Dream Portal nel Twilight Grove e raggiungi la Nightmare Incursion dello Yorgen Farmstead. Recupera un Unhatched Green Dragon Egg e portamelo.", nil, nil, 0x3941eba9, 0x03540759, 0xd172b113, nil, nil, "...mm" },
  [81739] = { "Missione di Duskwood X: Nightmare Moss", "Raccogli 10 Nightmare Moss nelle Duskwood Nightmare Incursion e torna dal Field Captain Palandar.", "Mentre questi demoni ci distraggono qui, l'Emerald Dream si sta corrompendo in incubo. Presto, attraversa l'Emerald Dream Portal nel Twilight Grove e raccogli del Nightmare Moss all'interno delle Nightmare Incursion. Possiamo sfruttarne la magia per rimediare ai danni. Ti servirà l'aiuto di un erborista.", nil, nil, 0x41d8371c, 0x2289c12b, 0x30adad8b, nil, nil, "...mm" },
  [81740] = { "Missione di Duskwood XI: Cold Iron Ore", "Raccogli 10 Cold Iron Ore nelle Duskwood Nightmare Incursion e torna dal Field Captain Palandar.", "Mentre questi demoni ci distraggono qui, l'Emerald Dream si sta corrompendo in incubo. Presto, attraversa l'Emerald Dream Portal nel Twilight Grove e raccogli del Cold Iron Ore all'interno delle Nightmare Incursion. Possiamo sfruttarne la magia per rimediare ai danni. Ti servirà l'aiuto di un minatore.", nil, nil, 0xb76951d2, 0xc96ad9fc, 0x620aa8b3, nil, nil, "...mm" },
  [81741] = { "Missione di Duskwood XII: Dream-Touched Dragonscale", "Raccogli 10 Dream-Touched Dragonscales nelle Duskwood Nightmare Incursion e torna dal Field Captain Palandar.", "Mentre questi demoni ci distraggono qui, l'Emerald Dream si sta corrompendo in incubo. Presto, attraversa l'Emerald Dream Portal nel Twilight Grove e raccogli le Dream-Touched Dragonscales dai draconidi all'interno delle Nightmare Incursion. Possiamo sfruttarne la magia per rimediare ai danni. Ti servirà l'aiuto di uno scuoiatore.", nil, nil, 0xb9ecbfdc, 0xa96c76e5, 0x0f3c381b, nil, nil, "...mm" },
  [81742] = { "Missione di Duskwood XIII: sconfiggi Ylanthrius", "Sconfiggi Ylanthrius nella Duskwood Nightmare Incursion nel campo dello Yorgen Farmstead e torna dal Field Captain Palandar.", "Mentre questi demoni ci distraggono qui, l'Emerald Dream si sta corrompendo in incubo. Presto, attraversa l'Emerald Dream Portal nel Twilight Grove e raggiungi la Nightmare Incursion dello Yorgen Farmstead. Sconfiggi il drago Ylanthrius e torna da me.", nil, nil, 0x54cddfe0, 0xada241be, 0xbd679dc1, nil, nil, "...mm" },
  [81743] = { "Missione di Duskwood XIV: sconfiggi Vvarc'zul", "Sconfiggi Vvarc'zul nella Duskwood Nightmare Incursion nel profondo del Vul'gol Ogre Mound e torna dal Field Captain Palandar.", "Mentre questi demoni ci distraggono qui, l'Emerald Dream si sta corrompendo in incubo. Presto, attraversa l'Emerald Dream Portal nel Twilight Grove e raggiungi la Nightmare Incursion del Vul'gol Ogre Mound. Sconfiggi il signore della guerra ogre Vvarc'zul e torna da me.", nil, nil, 0xac56912b, 0xb023e879, 0xe4140278, nil, nil, "...mm" },
  [81744] = { "Missione di Duskwood XV: sconfiggi Amokarok", "Sconfiggi Amokarok nella Duskwood Nightmare Incursion in un accampamento vicino al fienile del Rotting Orchard e torna dal Field Captain Palandar.", "Mentre questi demoni ci distraggono qui, l'Emerald Dream si sta corrompendo in incubo. Presto, attraversa l'Emerald Dream Portal nel Twilight Grove e raggiungi la Nightmare Incursion del Rotting Orchard. Sconfiggi il capo dei worgen Amokarok e torna da me.", nil, nil, 0x3f25090f, 0x63ef6a7c, 0x451996ef, nil, nil, "...mm" },
  [81745] = { "Missione di Duskwood XVI: salva Kroll Mountainshade", "Salva Kroll Mountainshade nella Duskwood Nightmare Incursion nella foresteria del Rotting Orchard e torna dal Field Captain Palandar.", "Mentre questi demoni ci distraggono qui, l'Emerald Dream si sta corrompendo in incubo. Presto, attraversa l'Emerald Dream Portal nel Twilight Grove e raggiungi la Nightmare Incursion del Rotting Orchard. Trova il Druid of the Claw addormentato Kroll Mountainshade e scortalo in salvo. Poi torna da me.", nil, nil, 0x24c25245, 0x2b8afb56, 0xd286b19d, nil, nil, "...mm" },
  [81746] = { "Missione di Duskwood XVII: salva Alara Grovemender", "Salva Alara Grovemender nella Duskwood Nightmare Incursion nella stalla dello Yorgen Farmstead e torna dal Field Captain Palandar.", "Mentre questi demoni ci distraggono qui, l'Emerald Dream si sta corrompendo in incubo. Presto, attraversa l'Emerald Dream Portal nel Twilight Grove e raggiungi la Nightmare Incursion dello Yorgen Darmstead. Trova la Druid of the Claw addormentata Alara Grovemender e scortala in salvo. Poi torna da me.", nil, nil, 0x8ffdbb57, 0xfed717a4, 0x247486e4, nil, nil, "...mm" },
  [81747] = { "Missione di Duskwood XVIII: salva Elenora Marshwalker", "Salva Elenora Marshwalker nella Duskwood Nightmare Incursion tra le rovine di una casa colonica vicino al Vul'gol Ogre Mound e torna dal Field Captain Palandar.", "Mentre questi demoni ci distraggono qui, l'Emerald Dream si sta corrompendo in incubo. Presto, attraversa l'Emerald Dream Portal nel Twilight Grove e raggiungi la Nightmare Incursion del Vul'gol Ogre Mound. Trova la Druid of the Claw addormentata Elenora Marshwalker e scortala in salvo. Poi torna da me.", nil, nil, 0xb211ed7e, 0x7aa89563, 0xbeca4a23, nil, nil, "...mm" },
  [81768] = { "Missione di Ashenvale I: sconfiggi i satiri", "Sconfiggi 10 Dreamfire Betrayer e 10 Dreamfire Hellcaller nell'Ashenvale Nightmare Incursion a Satyrnaar e torna dalla Field Captain Hannalah.", "Mentre questi demoni ci distraggono qui, l'Emerald Dream si sta corrompendo in incubo. Presto, attraversa l'Emerald Dream Portal a Bough Shadow e raggiungi la Nightmare Incursion di Satyrnaar. Sconfiggi i satiri che trovi e torna da me.", nil, nil, 0x47c92e86, 0xa6fa3002, 0xf586305e, nil, nil, "...mm" },
  [81769] = { "Missione di Ashenvale II: sconfiggi i treant", "Sconfiggi 7 Vengeful Ancient nell'Ashenvale Nightmare Incursion al Warsong Lumber Camp e torna dalla Field Captain Hannalah.", "Mentre questi demoni ci distraggono qui, l'Emerald Dream si sta corrompendo in incubo. Presto, attraversa l'Emerald Dream Portal a Bough Shadow e raggiungi la Nightmare Incursion del Warsong Lumber Camp. Sconfiggi i treant che trovi e torna da me.", nil, nil, 0x970dcc24, 0xa2bcb9e3, 0x5f795363, nil, nil, "...mm" },
  [81770] = { "Missione di Ashenvale III: sconfiggi i draconidi", "Sconfiggi 3 Wyrmkin Nightstalker e 10 Terror Whelp nell'Ashenvale Nightmare Incursion a Forest Song e torna dalla Field Captain Hannalah.", "Mentre questi demoni ci distraggono qui, l'Emerald Dream si sta corrompendo in incubo. Presto, attraversa l'Emerald Dream Portal a Bough Shadow e raggiungi la Nightmare Incursion di Forest Song. Sconfiggi i draconidi che trovi e torna da me.", nil, nil, 0x3f395462, 0xec098bc7, 0x3466c90b, nil, nil, "...mm" },
  [81771] = { "Missione di Ashenvale IV: informazioni sui draghi", "Raccogli informazioni dal Dreamwarden Ellodar nell'Ashenvale Nightmare Incursion a Forest Song, sul ponte verso l'antica torre e torna dalla Field Captain Hannalah.", "Mentre questi demoni ci distraggono qui, l'Emerald Dream si sta corrompendo in incubo. Presto, attraversa l'Emerald Dream Portal a Bough Shadow e raggiungi la Nightmare Incursion di Forest Song. Recupera un rapporto informativo dal Dreamwarden Ellodar e torna da me.", nil, nil, 0x8c6c658b, 0x432e9914, 0x23860bc7, nil, nil, "...mm" },
  [81772] = { "Missione di Ashenvale V: informazioni sui satiri", "Raccogli informazioni dal Dreamwarden Mandoran nell'Ashenvale Nightmare Incursion al cerchio rituale di Satyrnaar e torna dalla Field Captain Hannalah.", "Mentre questi demoni ci distraggono qui, l'Emerald Dream si sta corrompendo in incubo. Presto, attraversa l'Emerald Dream Portal a Bough Shadow e raggiungi la Nightmare Incursion di Satyrnaar. Recupera un rapporto informativo dal Dreamwarden Mandoran e torna da me.", nil, nil, 0x5df5bd06, 0xd0638a2c, 0x8cd6e645, nil, nil, "...mm" },
  [81773] = { "Missione di Ashenvale VI: informazioni sui treant", "Raccogli informazioni dalla Dreamwarden Lanaria nell'Ashenvale Nightmare Incursion dentro la Kargathia Keep, al Warsong Lumber Camp e torna dalla Field Captain Hannalah.", "Mentre questi demoni ci distraggono qui, l'Emerald Dream si sta corrompendo in incubo. Presto, attraversa l'Emerald Dream Portal a Bough Shadow e raggiungi la Nightmare Incursion del Warsong Lumber Camp. Recupera un rapporto informativo dalla Dreamwarden Lanaria e torna da me.", nil, nil, 0x7edfdfd4, 0xd521fb72, 0xdbf21bde, nil, nil, "...mm" },
  [81774] = { "Missione di Ashenvale VII: recupera il Dreamengine", "Recupera il Dreamengine nell'Ashenvale Nightmare Incursion dalla forgia del Warsong Lumber Camp e torna dalla Field Captain Hannalah.", "Mentre questi demoni ci distraggono qui, l'Emerald Dream si sta corrompendo in incubo. Presto, attraversa l'Emerald Dream Portal a Bough Shadow e raggiungi la Nightmare Incursion del Warsong Lumber Camp. Recupera un potente manufatto noto come Dreamengine e portamelo.", nil, nil, 0xa80b3dd7, 0xb9feeac4, 0xe7ba1cfb, nil, nil, "...mm" },
