  [81776] = { "Missione di Ashenvale IX: recupera il Dream-Touched Dragonegg", "Recupera un Dream-Touched Dragonegg nell'Ashenvale Nightmare Incursion dalla rovina centrale di Forest Song e torna dalla Field Captain Hannalah.", "Mentre questi demoni ci distraggono qui, l'Emerald Dream si sta corrompendo in incubo. Presto, attraversa l'Emerald Dream Portal a Bough Shadow e raggiungi la Nightmare Incursion di Forest Song. Recupera un Dream-Touched Dragonegg e portamelo.", nil, nil, 0xbc759dc6, 0xf57cca69, 0x90cfc82e, nil, nil, "...mm" },
